// Own: zzOWN.com - Own Fast. Work Faster.  | Ema: zzown.com@gmail.com
// Des: Tests for many accounts: rotation, caps, first-run move, rests
// Flo: fake runner per account (no browser) > assert order, results, rest marks in each account's own db, nothing shared
// I/O: scratch dir + sqlite (no Chrome) > pass or fail (no leaks)
// Run: zig build test -Dfile=ru-acct-main-test.zig
// ===================================================================
const std = @import("std"); const acct = @import("ru-acct-main.zig"); const cfgz = @import("cf-conf-load.zig"); const pace = @import("ru-huma-pace.zig");
const Fake = struct { seen: std.ArrayList([]const u8) = .empty, fail_id: []const u8 = "", fail_err: anyerror = error.Unsafe, aren: std.mem.Allocator, lines: u32 = 0 };
fn runF(px: ?*anyopaque, id: []const u8) anyerror!void { const fk: *Fake = @ptrCast(@alignCast(px.?)); try fk.seen.append(fk.aren, id); if (std.mem.eql(u8, id, fk.fail_id)) return fk.fail_err; }
fn sayF(px: ?*anyopaque, _: []const u8) void { const fk: *Fake = @ptrCast(@alignCast(px.?)); fk.lines += 1; }
fn envOf(fk: *Fake, aren: std.mem.Allocator, root: []const u8, ids: []const []const u8, now: i64, rng: *pace.Rng) acct.Env { var conf: cfgz.Conf = .{}; conf.time_scal_perc = 0; return .{ .aren = aren, .iozz = std.testing.io, .conf = conf, .root = root, .ids = ids, .now = now, .rng = rng, .ctx = fk, .run = runF, .say = sayF }; }
fn rootOf(tmp: *std.testing.TmpDir, al: std.mem.Allocator) ![]u8 { return std.fmt.allocPrint(al, ".zig-cache/tmp/{s}", .{tmp.sub_path}); }
test "order rotates by day so the same account is not always first" { var aren = std.heap.ArenaAllocator.init(std.testing.allocator); defer aren.deinit(); const ids = [_][]const u8{ "a", "b", "c" }; const o0 = try acct.order(aren.allocator(), &ids, 0); try std.testing.expectEqualStrings("a", o0[0]); const o1 = try acct.order(aren.allocator(), &ids, 86400000); try std.testing.expectEqualStrings("b", o1[0]); try std.testing.expectEqualStrings("a", o1[2]); const o3 = try acct.order(aren.allocator(), &ids, 3 * 86400000); try std.testing.expectEqualStrings("a", o3[0]); const none = try acct.order(aren.allocator(), &.{}, 5); try std.testing.expectEqual(@as(usize, 0), none.len); }
test "caps percent scales every capz key, keeps 0 as 0 and never drops a live cap to 0" { const conf: cfgz.Conf = .{}; const half = acct.applyScal(conf, 50); try std.testing.expectEqual(@as(u32, 1), half.capz_post_dayz); try std.testing.expectEqual(@as(u32, 15), half.capz_comm_dayz); try std.testing.expectEqual(@as(u32, 0), half.capz_mone_dayz); const same = acct.applyScal(conf, 100); try std.testing.expectEqual(conf.capz_comm_dayz, same.capz_comm_dayz); const tiny = acct.applyScal(conf, 1); try std.testing.expectEqual(@as(u32, 1), tiny.capz_post_dayz); try std.testing.expectEqual(@as(u32, 20), acct.applyScal(conf, 50).capz_help_dayz); }
test "the gap is random inside the configured seconds" { var rng = pace.Rng.init(7); const conf: cfgz.Conf = .{}; var ix: u32 = 0; while (ix < 50) : (ix += 1) { const gap = acct.gapMs(&rng, conf); try std.testing.expect(gap >= 300000 and gap <= 1200000); } }
test "first run moves the old prof and stat into acct/main and never deletes; a second run does nothing" { var tmp = std.testing.tmpDir(.{}); defer tmp.cleanup(); var aren = std.heap.ArenaAllocator.init(std.testing.allocator); defer aren.deinit(); const al = aren.allocator(); const root = try rootOf(&tmp, al); const cwd = std.Io.Dir.cwd(); try cwd.createDirPath(std.testing.io, try std.fmt.allocPrint(al, "{s}/stat", .{root})); try cwd.createDirPath(std.testing.io, try std.fmt.allocPrint(al, "{s}/prof", .{root})); try cwd.writeFile(std.testing.io, .{ .sub_path = try std.fmt.allocPrint(al, "{s}/stat/fb-state.db", .{root}), .data = "DB" }); try cwd.writeFile(std.testing.io, .{ .sub_path = try std.fmt.allocPrint(al, "{s}/prof/Cookies", .{root}), .data = "C" }); try std.testing.expect(try acct.migrate(al, std.testing.io, root)); const dbtxt = try cwd.readFileAlloc(std.testing.io, try std.fmt.allocPrint(al, "{s}/acct/main/stat/fb-state.db", .{root}), al, .limited(100)); try std.testing.expectEqualStrings("DB", dbtxt); _ = try cwd.readFileAlloc(std.testing.io, try std.fmt.allocPrint(al, "{s}/acct/main/prof/Cookies", .{root}), al, .limited(100)); try std.testing.expect(!(try acct.migrate(al, std.testing.io, root))); try std.testing.expectError(error.FileNotFound, cwd.access(std.testing.io, try std.fmt.allocPrint(al, "{s}/stat", .{root}), .{})); }
test "a fresh install migrates nothing but still creates acct/main" { var tmp = std.testing.tmpDir(.{}); defer tmp.cleanup(); var aren = std.heap.ArenaAllocator.init(std.testing.allocator); defer aren.deinit(); const al = aren.allocator(); const root = try rootOf(&tmp, al); try std.testing.expect(!(try acct.migrate(al, std.testing.io, root))); try std.Io.Dir.cwd().access(std.testing.io, try std.fmt.allocPrint(al, "{s}/acct/main", .{root}), .{}); }
test "all runs the accounts one by one in rotated order, a plain error on one does not stop the others" { var tmp = std.testing.tmpDir(.{}); defer tmp.cleanup(); var aren = std.heap.ArenaAllocator.init(std.testing.allocator); defer aren.deinit(); const al = aren.allocator(); const root = try rootOf(&tmp, al); var fk: Fake = .{ .aren = al, .fail_id = "b", .fail_err = error.NoElement }; var rng = pace.Rng.init(3); const ids = [_][]const u8{ "a", "b", "c" }; var env = envOf(&fk, al, root, &ids, 86400000, &rng); const res = try acct.runAll(&env); try std.testing.expectEqual(@as(usize, 3), res.len); try std.testing.expectEqualStrings("b", fk.seen.items[0]); try std.testing.expectEqualStrings("c", fk.seen.items[1]); try std.testing.expectEqualStrings("a", fk.seen.items[2]); try std.testing.expectEqualStrings("NoElement", res[0].state); try std.testing.expectEqual(@as(u8, 3), res[0].code); try std.testing.expectEqualStrings("ok", res[1].state); try std.testing.expectEqual(@as(u8, 3), acct.worst(res)); try std.testing.expect(acct.restUntil(&env, "b") == 0); }
test "an unsafe stop rests only that account (its own db); the next run skips it" { var tmp = std.testing.tmpDir(.{}); defer tmp.cleanup(); var aren = std.heap.ArenaAllocator.init(std.testing.allocator); defer aren.deinit(); const al = aren.allocator(); const root = try rootOf(&tmp, al); var fk: Fake = .{ .aren = al, .fail_id = "a" }; var rng = pace.Rng.init(3); const ids = [_][]const u8{ "a", "b", "c" }; var env = envOf(&fk, al, root, &ids, 1000, &rng); const res = try acct.runAll(&env); try std.testing.expectEqual(@as(usize, 3), res.len); try std.testing.expectEqual(@as(u8, 4), acct.worst(res)); try std.testing.expect(acct.restUntil(&env, "a") > 1000); try std.testing.expect(acct.restUntil(&env, "b") == 0); try std.testing.expect(acct.restUntil(&env, "c") == 0); fk.seen.clearRetainingCapacity(); fk.fail_id = ""; const res2 = try acct.runAll(&env); try std.testing.expectEqual(@as(usize, 3), res2.len); try std.testing.expectEqual(@as(usize, 2), fk.seen.items.len); var skipped: u32 = 0; for (res2) |rs| { if (std.mem.eql(u8, rs.state, "rest")) skipped += 1; } try std.testing.expectEqual(@as(u32, 1), skipped); }
test "two accounts resting = every other account rests and nothing runs" { var tmp = std.testing.tmpDir(.{}); defer tmp.cleanup(); var aren = std.heap.ArenaAllocator.init(std.testing.allocator); defer aren.deinit(); const al = aren.allocator(); const root = try rootOf(&tmp, al); var fk: Fake = .{ .aren = al }; var rng = pace.Rng.init(3); const ids = [_][]const u8{ "a", "b", "c" }; var env = envOf(&fk, al, root, &ids, 5000, &rng); acct.restSet(&env, "a"); acct.restSet(&env, "b"); const res = try acct.runAll(&env); try std.testing.expectEqual(@as(usize, 0), fk.seen.items.len); for (res) |rs| try std.testing.expectEqualStrings("rest", rs.state); try std.testing.expect(acct.restUntil(&env, "c") > 5000); }
test "an unsafe stop during the run, with one account already resting, rests the remaining accounts" { var tmp = std.testing.tmpDir(.{}); defer tmp.cleanup(); var aren = std.heap.ArenaAllocator.init(std.testing.allocator); defer aren.deinit(); const al = aren.allocator(); const root = try rootOf(&tmp, al); var fk: Fake = .{ .aren = al, .fail_id = "a" }; var rng = pace.Rng.init(3); const ids = [_][]const u8{ "a", "b", "c", "d" }; var env = envOf(&fk, al, root, &ids, 0, &rng); acct.restSet(&env, "d"); const res = try acct.runAll(&env); try std.testing.expectEqual(@as(usize, 1), fk.seen.items.len); try std.testing.expectEqualStrings("a", fk.seen.items[0]); try std.testing.expectEqualStrings("Unsafe", res[0].state); try std.testing.expectEqualStrings("rest", res[1].state); try std.testing.expect(acct.restUntil(&env, "b") > 0); try std.testing.expect(acct.restUntil(&env, "c") > 0); }
test "commands that do not use the browser run for every account without rests or gaps" { var tmp = std.testing.tmpDir(.{}); defer tmp.cleanup(); var aren = std.heap.ArenaAllocator.init(std.testing.allocator); defer aren.deinit(); const al = aren.allocator(); const root = try rootOf(&tmp, al); var fk: Fake = .{ .aren = al, .fail_id = "a" }; var rng = pace.Rng.init(3); const ids = [_][]const u8{ "a", "b" }; var env = envOf(&fk, al, root, &ids, 0, &rng); env.browser = false; const res = try acct.runAll(&env); try std.testing.expectEqual(@as(usize, 2), fk.seen.items.len); try std.testing.expectEqual(@as(usize, 2), res.len); try std.testing.expect(acct.restUntil(&env, "a") == 0); }
